/**
 * Coxswain visualizer highlight subscriber (W4, FR-11 / N8-B / §4.6).
 *
 * NEW conditionally-staged file (deviation D-C): staged and script-tagged into
 * visualizer/index.html ONLY under `build_repl.py --with-coxswain`. It is a
 * SIBLING of the augmentation file, never an edit to it -- that file ships in
 * every build, so Coxswain code inside it would falsify FR-12 and make AC-11's
 * byte-identity clause vacuous. This module is likewise NEVER regenerated by
 * vendor_visualizer.py; only the tag referencing it is injected.
 *
 * READ-ONLY by contract:
 *  - It subscribes to `praxis_coxswain` (Coxswain UI traffic) for highlights,
 *    and to `praxis_viz` ONLY to observe committed-state repaints, which wipe
 *    its overlay (a highlight of a stale location is a lie).
 *  - It draws exclusively on ONE dedicated Konva layer added to the vendored
 *    global stage (`HIGHLIGHT_LAYER_NAME`). No vendored draw code is forked or
 *    wrapped, no committed layer gains children through this module, and the
 *    committed-state model (`receiveFromPython`/`handleEvent`) is never called.
 *
 * §4.6 handshake: this document runs outside coxswain-shell.js and therefore
 * has no session of its own until the shell appends `?coxswain_session=<id>`
 * to the frame src. The id is read at module load; a matching `hello_ack`
 * gates EVERY highlight. Pre-handshake or foreign-session messages are
 * dropped (fail closed) with one debug line per session -- not per message.
 * A page opened directly has no parameter, never handshakes, never draws:
 * intended behavior, not degradation.
 *
 * SELF-CONTAINED on purpose: importing ../../shell/coxswain/highlight.js would
 * hardcode a relative depth that differs between the source tree and dist/
 * (RISK-11's fragility, self-inflicted). Directives arrive over the channel;
 * only the reduced-motion query string is duplicated here, with highlight.js
 * as its canonical definition.
 */

export const CHANNEL_NAME = "praxis_coxswain";
export const VIZ_CHANNEL_NAME = "praxis_viz";
export const HANDSHAKE_QUERY_PARAM = "coxswain_session";
export const HIGHLIGHT_LAYER_NAME = "coxswain-highlight-layer";

/** Canonical definition: web-repl/shell/coxswain/highlight.js. */
const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

function readSessionId(location) {
  try {
    return (
      new URLSearchParams((location && location.search) || "").get(
        HANDSHAKE_QUERY_PARAM,
      ) || null
    );
  } catch {
    return null;
  }
}

function plainObject(v) {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

/**
 * Build the subscriber. All environment handles are injected so the module is
 * unit-testable without Konva/BroadcastChannel/window (NFR-3's spirit, one
 * document over).
 *
 *   location          {search} -- the visualizer document's location
 *   channelFactory    (name) => BroadcastChannel-like instance
 *   konva             the vendored page's global Konva
 *   stage             the vendored renderer's global Konva stage
 *   matchMediaResult  result of matchMedia(REDUCED_MOTION_QUERY), or undefined
 *   timers            {setInterval,clearInterval,setTimeout}; injectable
 *   debug             (line) => void; one line per session, never per message
 */
export function createVizHighlight(env = {}) {
  const {
    location: loc,
    channelFactory,
    konva,
    stage,
    matchMediaResult,
    timers: timerIn,
    debug = () => {},
  } = env;
  const timers = timerIn ?? {
    setInterval: globalThis.setInterval.bind(globalThis),
    clearInterval: globalThis.clearInterval.bind(globalThis),
    setTimeout: globalThis.setTimeout.bind(globalThis),
  };

  const session_id = readSessionId(loc);
  let handshakeComplete = false;
  let ackLogged = false;
  let seq = 0;
  let pulseHandle = null;

  // No owning session -> no hello, no ack, no drawing, ever (§4.6's last para).
  let channel = null;
  if (session_id && typeof channelFactory === "function") {
    try {
      channel = channelFactory(CHANNEL_NAME);
      channel.onmessage = (ev) => handleEnvelope(ev && ev.data);
    } catch (err) {
      debug(`broadcastchannel unavailable: ${err && err.message}`);
      channel = null;
    }
  }

  if (!session_id) {
    debug("no coxswain_session parameter; highlight subscriber stays inert");
  } else {
    postHello();
  }

  function nextSeq() {
    return seq++;
  }

  function postHello() {
    if (!channel) return;
    try {
      channel.postMessage({
        v: 1,
        session_id,
        turn_id: null,
        kind: "coxswain.hello",
        seq: nextSeq(),
        ts: Date.now(),
      });
    } catch (err) {
      debug(`hello post failed: ${err && err.message}`);
    }
  }

  function handleEnvelope(msg) {
    if (!plainObject(msg)) return;
    if (msg.v !== 1 || typeof msg.kind !== "string" || typeof msg.session_id !== "string") {
      return; // malformed: dropped, fail closed
    }

    if (msg.kind === "coxswain.hello_ack") {
      if (msg.session_id === session_id) {
        handshakeComplete = true;
        if (!ackLogged) {
          ackLogged = true; // ONE debug line per session, not per message
          debug(`hello_ack received for ${msg.session_id}; highlights enabled`);
        }
      }
      return;
    }

    if (msg.kind === "viz.highlight" || msg.kind === "viz.highlight.clear") {
      // Fail closed: pre-handshake AND foreign-session traffic draws nothing.
      if (!handshakeComplete || msg.session_id !== session_id) return;
      if (msg.kind === "viz.highlight.clear") {
        clearOverlay();
        return;
      }
      const directive = msg.payload && msg.payload.directive;
      if (!plainObject(directive)) return;
      applyDirective(directive);
    }
    // Unknown kinds are ignored silently: this document renders state only.
  }

  // --- dedicated overlay layer -------------------------------------------------

  function ensureLayer() {
    if (!stage || typeof stage.getLayers !== "function" || !konva) return null;
    const existing = stage
      .getLayers()
      .find((l) => l && l.attrs && l.attrs.name === HIGHLIGHT_LAYER_NAME);
    if (existing) return existing;
    if (typeof stage.add !== "function" || !konva.Layer) return null;
    const layer = new konva.Layer({ name: HIGHLIGHT_LAYER_NAME, listening: false });
    stage.add(layer);
    return layer;
  }

  function findCommittedNodes(label) {
    const hits = [];
    for (const layer of stage.getLayers()) {
      if (!layer || layer.attrs?.name === HIGHLIGHT_LAYER_NAME) continue;
      for (const node of layer.children || []) {
        if (node.attrs && node.attrs.name === label) hits.push(node);
      }
    }
    return hits;
  }

  function motionAllowed() {
    // AC-12/NFR-6: unreadable preference fails closed to static rendering.
    const reduced =
      plainObject(matchMediaResult) ? matchMediaResult.matches === true : true;
    return !reduced;
  }

  function applyDirective(directive) {
    stopPulse();
    const shapes = Array.isArray(directive.shapes) ? directive.shapes : [];
    const layer = ensureLayer();
    if (!layer) return;

    const animateWanted = directive.animate === true && Number(directive.frames) > 0;
    const animate = animateWanted && motionAllowed();

    const outlines = [];
    const unmatched = [];
    for (const shape of shapes) {
      const label = shape && typeof shape.label === "string" ? shape.label : "";
      if (!label) continue;
      const targets = findCommittedNodes(label);
      if (targets.length === 0) {
        unmatched.push(label);
        continue;
      }
      for (const t of targets) {
        const rect = new konva.Rect({
          name: `${HIGHLIGHT_LAYER_NAME}-rect`,
          x: Number(t.attrs.x ?? 0),
          y: Number(t.attrs.y ?? 0),
          width: Number(t.attrs.width ?? 0),
          height: Number(t.attrs.height ?? 0),
          stroke: "#ff8a00",
          strokeWidth: animate ? 2 : 3,
          dash: [6, 4],
          listening: false,
        });
        layer.add(rect);
        outlines.push(rect);
      }
    }

    if (unmatched.length > 0) {
      // Degrade VISIBLY: a labelled badge beats a silent no-op.
      layer.add(
        new konva.Text({
          name: `${HIGHLIGHT_LAYER_NAME}-badge`,
          x: 8,
          y: 8,
          text: `Coxswain highlight (not found on deck): ${unmatched.join(", ")}`,
          fontSize: 12,
          fill: "#b45309",
          listening: false,
        }),
      );
    }

    layer.batchDraw();
    if (animate && outlines.length > 0) {
      startPulse(outlines, layer, Number(directive.frames), Number(directive.period_ms) || 800);
    }
  }

  /** Pulse within the directive's own frame budget; directive.frames bounds it. */
  function startPulse(outlines, layer, frames, periodMs) {
    let ticks = Math.max(1, frames);
    let wide = false;
    pulseHandle = timers.setInterval(() => {
      wide = !wide;
      for (const rect of outlines) rect.attrs.strokeWidth = wide ? 4 : 2;
      layer.batchDraw();
      ticks -= 1;
      if (ticks <= 0) stopPulse();
    }, periodMs);
  }

  function stopPulse() {
    if (pulseHandle !== null) {
      timers.clearInterval(pulseHandle);
      pulseHandle = null;
    }
  }

  function clearOverlay() {
    stopPulse();
    const layer = ensureLayer();
    if (layer && typeof layer.destroyChildren === "function") {
      layer.destroyChildren();
      layer.batchDraw();
    }
  }

  // Committed-state repaints wipe the overlay: observe praxis_viz READ-ONLY.
  let vizChannel = null;
  if (session_id && typeof channelFactory === "function") {
    try {
      vizChannel = channelFactory(VIZ_CHANNEL_NAME);
      vizChannel.onmessage = () => clearOverlay();
    } catch {
      vizChannel = null; // repaint-wipe degrades to directive-driven clears
    }
  }

  return {
    session_id,
    handshakeComplete: () => handshakeComplete,
    handleEnvelope,
    applyDirective,
    clearOverlay,
    destroy() {
      stopPulse();
      try {
        channel?.close();
        vizChannel?.close();
      } catch {}
    },
  };
}

// --- browser auto-init ---------------------------------------------------------
// Runs only in the real visualizer document; bun tests import the factory.

if (
  typeof window !== "undefined" &&
  typeof document !== "undefined" &&
  !globalThis.__COXSWAIN_VIZ_HIGHLIGHT_TEST__
) {
  try {
    const factory =
      typeof BroadcastChannel === "function"
        ? (name) => new BroadcastChannel(name)
        : null;
    const media =
      typeof window.matchMedia === "function"
        ? window.matchMedia(REDUCED_MOTION_QUERY)
        : undefined;
    const viz = createVizHighlight({
      location: window.location,
      channelFactory: factory,
      konva: window.Konva ?? globalThis.Konva,
      stage: window.stage ?? globalThis.stage,
      matchMediaResult: media,
      debug: (line) => console.debug(`[coxswain-viz] ${line}`),
    });
    globalThis.__praxisCoxswainVizHighlight = viz;
  } catch (err) {
    console.error("[coxswain-viz] init failed:", err && err.message);
  }
}
